<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__,2).'/app/autoload.php';
use FMonitor2\InstallationProcess\JobsSchemaMigration;use FMonitor2\Jobs\MariaDbJobQueue;
assertSameValue(true,class_exists(MariaDbJobQueue::class)&&class_exists(JobsSchemaMigration::class),'INTENTIONAL_RED: public durable queue and canonical schema owner exist');
mysqli_report(MYSQLI_REPORT_ERROR|MYSQLI_REPORT_STRICT);$host=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$user=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$password=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$name='t_jobs_'.bin2hex(random_bytes(5));$admin=new mysqli($host,$user,$password,'',$port);$admin->query("CREATE DATABASE `{$name}` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$db=new mysqli($host,$user,$password,$name,$port);$p='jobs_';$now='2026-09-09T07:00:00.000000Z';$tokens=[str_repeat('a',64),str_repeat('b',64),str_repeat('c',64)];
try{assertSameValue(true,JobsSchemaMigration::apply($db,$p)['applied'],'canonical jobs schema');$clock=static function()use(&$now):string{return$now;};$token=static function()use(&$tokens):string{return array_shift($tokens)??str_repeat('d',64);};$queue=new MariaDbJobQueue($db,$p,$clock,$token,['test.echo'=>[1],'test.dead'=>[1]]);
    $a=['jobType'=>'test.echo','payloadVersion'=>1,'payload'=>['value'=>'A'],'availableAtUtc'=>$now,'idempotencyKey'=>'11111111-1111-4111-8111-111111111111','actor'=>['type'=>'system','id'=>'scheduler']];$b=array_replace($a,['payload'=>['value'=>'B'],'idempotencyKey'=>'22222222-2222-4222-8222-222222222222']);
    $reject=static function(array$command,string$label)use($queue,$db,$p):void{$before=[(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_jobs`")->fetch_assoc()['n'],(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_job_events`")->fetch_assoc()['n']];try{$queue->enqueue($command);throw new TestFailure("{$label} accepted");}catch(InvalidArgumentException){}assertSameValue($before,[(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_jobs`")->fetch_assoc()['n'],(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_job_events`")->fetch_assoc()['n']],"{$label} rejected before persistence");};
    $reject(array_replace($a,['jobType'=>'unknown.type']),'unsupported type');$reject(array_replace($a,['payloadVersion'=>2]),'unsupported version');$reject(array_replace($a,['payload'=>['nested'=>['secret'=>'forbidden']]]),'nested secret');$reject(array_replace($a,['payload'=>['value'=>str_repeat('x',65536)]]),'oversized payload');
    $first=$queue->enqueue($a);assertSameValue('created',$first['status'],'new job created');$replay=$queue->enqueue($a);assertSameValue(['replayed',(int)$first['jobId']],[$replay['status'],(int)$replay['jobId']],'exact enqueue replay returns same identity');$conflict=$a;$conflict['payload']=['value'=>'changed'];assertSameValue('conflict',$queue->enqueue($conflict)['status'],'same key different fingerprint conflicts');$second=$queue->enqueue($b);
    $one=$queue->claim(['workerId'=>'worker-a','batch'=>1]);$two=$queue->claim(['workerId'=>'worker-b','batch'=>1]);assertSameValue([(int)$first['jobId'],(int)$second['jobId']],[(int)$one[0]['jobId'],(int)$two[0]['jobId']],'sequential batch1 claims use stable id order');assertSameValue([], $queue->claim(['workerId'=>'worker-c','batch'=>1]),'active leases excluded');
    $heartbeatBefore=$db->query("SELECT lease_expires_at_utc FROM `{$p}fm2_jobs` WHERE job_id=".(int)$one[0]['jobId'])->fetch_column();assertSameValue('too_soon',$queue->heartbeat(['jobId'=>$one[0]['jobId'],'leaseToken'=>$one[0]['leaseToken']])['status'],'heartbeat before 60 seconds rejected');assertSameValue($heartbeatBefore,$db->query("SELECT lease_expires_at_utc FROM `{$p}fm2_jobs` WHERE job_id=".(int)$one[0]['jobId'])->fetch_column(),'early heartbeat does not extend lease');$now='2026-09-09T07:01:00.000000Z';assertSameValue('accepted',$queue->heartbeat(['jobId'=>$one[0]['jobId'],'leaseToken'=>$one[0]['leaseToken']])['status'],'current heartbeat accepted after one minute');assertSameValue('completed',$queue->complete(['jobId'=>$two[0]['jobId'],'leaseToken'=>$two[0]['leaseToken'],'result'=>['ok'=>true]])['status'],'neighbor job completes under current token');$now='2026-09-09T07:04:00.000000Z';assertSameValue('stale_lease',$queue->complete(['jobId'=>$one[0]['jobId'],'leaseToken'=>str_repeat('f',64),'result'=>['ok'=>true]])['status'],'wrong token changes nothing');$now='2026-09-09T07:06:00.000001Z';$reclaimed=$queue->claim(['workerId'=>'worker-c','batch'=>1]);assertSameValue([2,str_repeat('c',64)],[(int)$reclaimed[0]['attempt'],$reclaimed[0]['leaseToken']],'expired lease reclaimed with new attempt/token');assertSameValue('stale_lease',$queue->complete(['jobId'=>$one[0]['jobId'],'leaseToken'=>$one[0]['leaseToken'],'result'=>['ok'=>true]])['status'],'old result rejected after reclaim');assertSameValue('completed',$queue->complete(['jobId'=>$one[0]['jobId'],'leaseToken'=>$reclaimed[0]['leaseToken'],'result'=>['ok'=>true]])['status'],'reclaimed job completes once');
    $retryCommand=array_replace($a,['payload'=>['value'=>'retry'],'availableAtUtc'=>$now,'idempotencyKey'=>'33333333-3333-4333-8333-333333333333']);$retryJob=$queue->enqueue($retryCommand);$tokens[] = str_repeat('d',64);$retryLease=$queue->claim(['workerId'=>'worker-r','batch'=>1])[0];$retryTimes=[];foreach([1,2,3,4,5]as$attempt){$result=$queue->fail(['jobId'=>$retryJob['jobId'],'leaseToken'=>$retryLease['leaseToken'],'failureCode'=>'TEST_RETRY','retryable'=>true]);$retryTimes[]=$result['availableAtUtc']??$result['status'];if($attempt<5){$now=$result['availableAtUtc'];$tokens[] = str_repeat((string)($attempt+3),64);$retryLease=$queue->claim(['workerId'=>'worker-r','batch'=>1])[0];}}
    assertSameValue(['2026-09-09T07:07:00.000001Z','2026-09-09T07:12:00.000001Z','2026-09-09T07:27:00.000001Z','2026-09-09T08:27:00.000001Z','dead'],$retryTimes,'exact retry delays and fifth dead');
    $expiryCommand=array_replace($a,['payload'=>['value'=>'expiry-five'],'availableAtUtc'=>$now,'idempotencyKey'=>'44444444-4444-4444-8444-444444444444']);$expiryJob=$queue->enqueue($expiryCommand);$expiryTokens=[str_repeat('8',64),str_repeat('9',64),str_repeat('a',64),str_repeat('b',64),str_repeat('c',64)];$tokens=array_merge($tokens,$expiryTokens);$expiryLease=$queue->claim(['workerId'=>'worker-expiry','batch'=>1])[0];$observedTokens=[$expiryLease['leaseToken']];foreach([60,300,900,3600]as$delay){$failed=$queue->fail(['jobId'=>$expiryJob['jobId'],'leaseToken'=>$expiryLease['leaseToken'],'failureCode'=>'TEST_RETRY','retryable'=>true]);$now=$failed['availableAtUtc'];$oldToken=$expiryLease['leaseToken'];$expiryLease=$queue->claim(['workerId'=>'worker-expiry','batch'=>1])[0];$observedTokens[]=$expiryLease['leaseToken'];$stateBefore=$db->query("SELECT status,attempt,lease_token FROM `{$p}fm2_jobs` WHERE job_id=".(int)$expiryJob['jobId'])->fetch_assoc();assertSameValue('stale_lease',$queue->complete(['jobId'=>$expiryJob['jobId'],'leaseToken'=>$oldToken,'result'=>['ok'=>true]])['status'],'earlier expiry token rejected after reclaim');assertSameValue($stateBefore,$db->query("SELECT status,attempt,lease_token FROM `{$p}fm2_jobs` WHERE job_id=".(int)$expiryJob['jobId'])->fetch_assoc(),'stale expiry token zero mutation');}assertSameValue($expiryTokens,$observedTokens,'every expiry attempt receives a distinct exact token');assertSameValue(5,(int)$expiryLease['attempt'],'expiry fixture reaches fifth lease');$now=(new DateTimeImmutable($expiryLease['leaseExpiresAtUtc']))->modify('+1 microsecond')->format('Y-m-d\TH:i:s.u\Z');assertSameValue([], $queue->claim(['workerId'=>'worker-six','batch'=>1]),'expired fifth lease never creates attempt six');assertSameValue('dead',$db->query("SELECT status FROM `{$p}fm2_jobs` WHERE job_id=".(int)$expiryJob['jobId'])->fetch_column(),'expired fifth lease becomes dead');$terminal=array_column($db->query("SELECT event_type FROM `{$p}fm2_job_events` WHERE job_id=".(int)$expiryJob['jobId']." ORDER BY event_id DESC LIMIT 2")->fetch_all(MYSQLI_ASSOC),'event_type');assertSameValue(['dead','expired'],$terminal,'expired fifth lease appends exact terminal history');
    $events=$db->query("SELECT event_type FROM `{$p}fm2_job_events` WHERE job_id=".(int)$first['jobId']." ORDER BY event_id")->fetch_all(MYSQLI_ASSOC);assertSameValue(true,count($events)>=7,'append-only lifecycle history retained');echo"PASS: DURABLE-BACKGROUND-JOBS-001 durable queue lifecycle\n";
}finally{$db->close();$admin->query("DROP DATABASE IF EXISTS `{$name}`");$admin->close();}
